const maqSlide = (n: 1 | 2 | 3, k: string, ph: { eyebrow: string; title: string; subtitle: string; button: string }): TextFieldDef[] => {
  const g = `Hero · Slide ${n}`;
  return [
    { key: `${k}OnlyImage`, label: `Slide ${n}: solo imagen`, placeholder: '', group: g, type: 'toggle', hint: `Sin textos ni botón; el banner completo lleva al enlace del Slide ${n}.` },
    { key: `${k}Eyebrow`, label: `Slide ${n}: etiqueta superior`, placeholder: ph.eyebrow, group: g, hint: 'Déjala vacía para ocultarla.' },
    { key: `${k}Title`, label: `Slide ${n}: título`, placeholder: ph.title, group: g, hint: 'Usa | para saltar de línea (ej. Brilla.|Define.|Sé tú.).' },
    { key: `${k}Subtitle`, label: `Slide ${n}: subtítulo`, placeholder: ph.subtitle, group: g, hint: 'Déjalo vacío para ocultarlo.' },
    { key: `${k}Button`, label: `Slide ${n}: botón`, placeholder: ph.button, group: g },
  ];
};

